async def seed_coding_problems(db: AsyncIOMotorDatabase) -> None:
    """Idempotently seed standard coding problems into MongoDB collection."""
    col = db["coding_problems"]
    now = datetime.now(timezone.utc)

    for item in CODING_PROBLEMS_SEED_DATA:
        existing = await col.find_one({"slug": item["slug"]})
        if not existing:
            doc = dict(item)
            doc["is_active"] = doc.get("is_active", True)
            doc["supported_languages"] = doc.get("supported_languages", ["python", "javascript", "typescript", "java", "cpp", "go"])
            doc["created_at"] = now
            doc["updated_at"] = now
            await col.insert_one(doc)
            logger.info("Seeded coding problem: %s (%s)", item["title"], item["slug"])
        else:
            # Update fields in case seed specifications evolved
            await col.update_one(
                {"slug": item["slug"]},
                {
                    "$set": {
                        "title": item["title"],
                        "difficulty": item["difficulty"],
                        "category": item["category"],
                        "topics": item["topics"],
                        "description": item["description"],
                        "constraints": item["constraints"],
                        "examples": item["examples"],
                        "sample_test_cases": item["sample_test_cases"],
                        "hidden_test_cases": item["hidden_test_cases"],
                        "supported_languages": item.get("supported_languages", ["python", "javascript", "typescript", "java", "cpp", "go"]),
                        "starter_code": item["starter_code"],
                        "is_active": item.get("is_active", True),
                        "updated_at": now,
                    }
                },
            )
